# The sheet's audit lines exactly as the audit file holds them, newest first; with ?name= only the lines carrying
# name=<the name> or person=<the name> (compared as names are). 404 for an id never loaded.
load:
  class: net.officefloor.hq.app.sheet.LoadSheet
  govern: [ readonly-transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.audit.RespondWithAuditLines
  govern: [ readonly-transaction ]
# Open a claim's editor: lock it for the user until the editor is saved or cancelled, or the sheet's today changes. A refused lock (unknown claim, a claim that is not a DRAFT or is due in a closed period, a claim another user holds locked) writes nothing.
validate:
  class: net.officefloor.hq.app.claim.ValidateClaimLock
  next: load
load:
  class: net.officefloor.hq.app.claim.LoadClaim
  govern: [ transaction ]
  next: draft
draft:
  class: net.officefloor.hq.app.claim.RefuseNonDraftClaimEdit
  govern: [ transaction ]
  next: closed
closed:
  class: net.officefloor.hq.app.period.RefuseClosedClaimLock
  govern: [ transaction ]
  next: save
save:
  class: net.officefloor.hq.app.claim.SaveClaimLock
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaim
  govern: [ transaction ]
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.plugin.variable.Val;

/** Record the stored add in the audit file, with the amount and date as the screen shows them, and its reference and its tags when it has them. */
public class AuditClaimAdded {
    public void audit(@Val ClaimInput input, @Val Person person, @Val Claim claim, Audit audit) {
        record(input, person, claim, audit);
    }

    /** The CLAIM_ADDED line for one stored add, then LATE_ENTRY for a late entry (the paste box writes one per line it adds). */
    static void record(ClaimInput input, Person person, Claim claim, Audit audit) {
        ClaimResponse shown = ClaimResponse.from(claim);
        audit.record("CLAIM_ADDED sheet=" + claim.sheetId() + " by=" + input.user()
                + " person=" + person.name() + " amount=" + shown.amount() + " date=" + shown.date()
                + (claim.ref() != null ? " ref=" + claim.ref() : "")
                + (claim.tags() != null ? " tags=" + claim.tags() : ""));
        if (claim.lateEntry()) {
            audit.record("LATE_ENTRY sheet=" + claim.sheetId() + " by=" + input.user()
                    + " person=" + person.name() + " amount=" + shown.amount() + " date=" + shown.date());
        }
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.watch.WatchRepository;
import net.officefloor.plugin.variable.Val;

/** Record the stored status change in the audit file, with the amount and date as the screen shows them,
 *  and the claim's number (for a void, the number it had); a settle or approve adds the due it fixed
 *  (n/a when the grade had no rate), a reject its reason, a void of a SETTLED claim reversed=<the frozen figure it had>. A settle, approve or re-settle that left it SETTLED
 *  is followed by one NOTIFY line per user watching its person, in the order they started watching. A settle that left the claim PENDING is CLAIM_PENDING. */
public class AuditClaimStatus {
    public void audit(@Val ClaimStatusInput input, @Val Claim loaded, @Val ClaimResponse saved,
            PersonRepository people, WatchRepository watches, Audit audit) {
        ClaimStatusChange.audit(input, loaded, saved, people, watches, audit);
    }
}
